/* GPL-3.0-only. Native scenario PCM + complete DSP state reference oracle.
 * Build this file twice against UNMODIFIED V4.0 and V4.1 engines, then
 * byte-compare stdout. No fixtures generated by the firmware under test. */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include "b1_engine.h"
static struct b1_engine e;
static int16_t pcm[4096u*2u];
static uint64_t hash=UINT64_C(14695981039346656037);
static void hash_bytes(const void *buf,size_t n){
 const uint8_t *p=buf;
 for(size_t i=0;i<n;i++){hash^=p[i];hash*=UINT64_C(1099511628211);}
}
static void run(uint32_t n){
 for(uint32_t i=0;i<8192u;i++)pcm[i]=(int16_t)0x5a5a;
 b1_render_stereo(&e,pcm,n);
 hash_bytes(pcm,n*2u*sizeof(int16_t));
}
static void snapshot(unsigned scenario,unsigned stage){
 uint64_t saved=hash;
 hash_bytes(&e,sizeof e);
 printf("scene=%u stage=%u pcm+state=%016llx wheel=%u fx=%u gate=%u\n",scenario,stage,
 (unsigned long long)hash,e.wheel_frame,e.fx_clear_step,e.output_gate_q15);
 hash=saved;
}
static void silence(uint32_t n){
 while(n>=128u){run(128u);n-=128u;}
 if(n)run(n);
}
int main(void){
 for(unsigned mode=0;mode<2;mode++)for(unsigned relief=0;relief<2;relief++){
  const unsigned scenario=mode*2u+relief;
  hash=UINT64_C(14695981039346656037);
  b1_reset(&e);e.cpu_relief=(uint8_t)relief;e.osc_mode=(uint8_t)mode;
  /* Until the existing incremental FX ring clearing has completed. */
  silence(B1_DELAY_SAMPLES+128u);
  snapshot(scenario,0);
  /* Seconds of quiescence while user edits osc, drawbars and FX. */
  silence(187904u);
  b1_drawbar(&e,0u,1u,0u);
  b1_drawbar(&e,1u,6u,8u);
  e.osc_mode=(uint8_t)(1u-mode);
  silence(173u);silence(8513u);
  e.osc_mode=(uint8_t)mode;
  silence(107u);silence(553u);
  snapshot(scenario,1);
  /* Sample-accurate wake-up, various non-power-of-two DMA sub-blocks. */
  b1_note_on(&e,60u,0u,100u);run(1u);run(63u);run(64u);
  b1_note_on(&e,67u,0u,100u);run(128u);
  b1_note_on(&e,72u,2u,100u);run(127u);
  e.delay_mix=38u;e.delay_time=67u;e.reverb_type=3u;
  e.reverb_mix=42u;e.rotor_fast=0u;e.cv_mode=4u;e.cv_depth=88u;
  silence(1900u);snapshot(scenario,2);
  b1_note_off(&e,60u,0u);b1_note_off(&e,67u,0u);
  b1_note_off(&e,72u,2u);
  silence(152000u);snapshot(scenario,3);
  silence(17123u);snapshot(scenario,4);
  b1_note_on(&e,48u,1u,90u);silence(1024u);
  b1_note_off(&e,48u,1u);silence(142000u);
  snapshot(scenario,5);
  /* Force near-32-bit frame wrap, must run the ordinary renderer. */
  e.wheel_frame=UINT32_MAX-48u;
  silence(128u);
  snapshot(scenario,6);
  b1_note_on(&e,55u,0u,120u);
  run(128u);snapshot(scenario,7);
 }
 return 0;
}
